after:
```swift
func accepted(_ values: [Int]) -> [Int] {
    var result: [Int] = []
    for value in values {
        if value == 0 {
            break
        }
        if value < 0 {
            continue
        }
        result.append(value)
    }
    return result
}
print(accepted([4, -2, 7, 0, 9]))
```
The result is `[4, 7]`. The loop keeps 4, skips -2, keeps 7, then stops at 0. It never adds 9.
